const std = @import("std");
const notui = @import("notui");

pub fn main(_: std.process.Init) void {
    var cluster: notui.markdown.Sanitizer = .{};
    var copying: notui.markdown.Sanitizer = .{};
    _ = cluster.accept(0x1b);
    _ = copying.accept(0x1b);
    const prior = cluster.state;
    const kept = cluster.acceptCluster("a\xff");
    var out: [2]u8 = undefined;
    const written = copying.copy(&out, "a\xff");
    std.debug.print(
        "invalid cluster: keep={any} state_before={s} state_after={s}; copy: written={d} state={s}\n",
        .{ kept, @tagName(prior), @tagName(cluster.state), written, @tagName(copying.state) },
    );
    const next_kept = cluster.accept('b');
    std.debug.print("next printable b kept={any}; documented unchanged-state rule would leave escape and reject b\n", .{next_kept});
}
